from heapq import heappush, heappop
from collections.abc import Callable

def shortest_path(graph: dict, source: str, target: str) -> (float, list[str]):
    # If source and target are the same, only one edge exists.
    if source == target:
        return 0, [source]

    # Priority queue for Dijkstra’s algorithm with priority: distance to node, current node
    priority_queue = [(0, source)]
    # Mapping for current shortest distance to each node to determine whether it has been expanded yet
    distance = {v: float("inf") for v, _ in graph.keys()}
    distance[source] = 0

    while priority_queue:
        cur_shortest_dist, node = heappop(priority_queue)

        # If reached the target, return the path
        if node == target:
            return cur_shortest_dist, reconstruct_path(graph, distance, source, target)

        for neighbor, edge_weight in graph.get(node, []):
            alt = cur_shortest_dist + edge_weight

            if alt >= distance[neighbor]:
                continue

            distance[neighbor] = alt
            heappush(priority_queue, (alt, neighbor))

    # If the target is unreachable.
    return float("inf"), []


def reconstruct_path(graph: dict, distance: dict, source: str, target: list[str]) -> list:
    path_back = deque(maxlen=len(distance))
    cur_node_path = deque()
    while graph:
        min_dist, node = min(
            (distance[ncn], ncn)
            for ncn, dist in graph.items()
            if ncn not in cur_node_path and node == source
        )
        if min_dist > float("inf"):
            break
        cur_node_path.appendleft(node)
        path_back.appendleft(node)
        graph = {nc: d[nc]
              for nc, d in graph.items()
              if nc not in cur_node_path}
    cur_node_path.extend(graph.get(source))

    path_back.extend(cur_node_path)
    return list(path_back)


