def shortest_path(graph, source, target):
    # Initialize distance for the source as (source itself) with 0 weight
    distances = {source: 0}
    # Initialize a dictionary to store the previous node in the shortest path tree
    previous_nodes = {source: None}
    # The queue to perform BFS
    from collections import deque
    nodes_to_explore = deque([source])

    while nodes_to_explore:
        current_node = nodes_to_explore.popleft()

        # If destination is reached, we return (distance, path)
        if current_node == target:
            path = []
            while current_node is not None:
                path.append(current_node)
                next_node = previous_nodes[current_node]
                current_node = next_node
            path.reverse()
            distance = distances[target]
            return (distance, path)

        # Explore each neighbor for the currently processed node.
        for neighbor, weight in graph.get(current_node, []):
            current_distance = distances.get(neighbor, float("inf"))
            proposed_distance = distances[current_node] + weight

            # Update if a shorter path to the neighbor is discovered.
            if proposed_distance < current_distance:
                distances[neighbor] = proposed_distance
                previous_nodes[neighbor] = current_node
                nodes_to_explore.append(neighbor)

    # If target cannot be reached.
    return (float("inf"), None)

