def path_exists(graph, source, target):
	'''
	Returns a tuple (distance, [path]) where distance is the distance 
	from source to target, path is a list of visited nodes (including source and 
	target).
	If there exists no path between the two nodes, returns (-1, []). 

	In practice one might use Dijkstra's algorithm or BFS for the actual calculation
	but we only require you provide a structure for this logic. 

	For the implementation, the graph will be given in the format of a dictionary,
	where each key is a Node object, and each value is a list. Each element in 
	the list is another dictionary representing a neighbour and its weight.
	Example:
		{0: [{1: 1, 'weight': 1}, {3: 3, 'weight': 5}], 1: [...], ...}
	'''
	if source not in graph or target not in graph:
		return (-1, [])

	path_set = {source}
	previous_node = {}
	distance_so_far = {source : 0}

	while path_set: 
		current_node = min(path_set, key = lambda node: distance_so_far[node])
		if current_node == target:
			break

		for neibor in graph[current_node] and list(map(lambda n : n.keys(), graph[current_node])):
			for neighbor_key in neibor:
				# Check to make sure there's no cycles 
				if neighbor_key != previous_node.keys() and (previous_node in distance_so_far or neighbor_key != current_node):				
					distance_new_path = distance_so_far[current_node] + distance_so_far.get(neighbor_key, neighbor_key)

					old_distance = distance_so_far.get(neighbor_key, None)
					# If there's not a better path found
					if old_distance == None or distance_new_path <= old_distance:
						distance_so_far[neighbor_key] = distance_new_path	
						previous_node[neighbor_key] = current_node
						path_set.add(neighbor_key)

			### Backtracking the path to calculate shortest path distance ###
			track = [target] if target != source else [target, source]
			node = current_node

			# Track the way backward and check for better paths.
			while node in path_set != source: 
				track.insert(0, previous_node[node])
				node = previous_node[node]

			# Remove source if it exists
			track[0] = previous_node[source]

			return (distance_so_far, track)


	track[0] = previous_node[source]

	# Return (infinity, False) is there's no path.
	return (-1, [])

