def shortest_path(graph, source, target):
    # Initialize data structures
    visited = {source: 0}
    paths = {source: [source]}
    queue = [(0, source)]  # (current distance, current node)

    # While the queue is not empty:
    while queue:
        (curr_dist, curr_vertex) = heapq.heappop(queue)  # Take vertex with smallest distance

        # If current node is target, return (distance, list of path)
        if curr_vertex == target:
            return (curr_dist, paths[curr_vertex])

        for (neighbour, weight) in graph[curr_vertex]:
            distance = curr_dist + weight

            # Only continue this iteration if it's the minimum distance found so far
            if neighbour in visited and distance >= visited[neighbour]:
                continue
            # If it's new node OR we can shorten the path for a current neighbor
            if neighbour not in visited or distance < visited[neighbour]:
                visit_distance = paths[curr_vertex][:]
                visit_distance.append(neighbour)

                # Update distances
                visited[neighbour] = distance
                paths[neighbour] = visit_distance

                # Push (distance, neigbhour) to the heap queue
                heapq.heappush(queue, (distance, neighbour))

    # If we reach a point, where no path is found to 'neighbout', return float('inf'), (None)
    return (float("inf"), None)

