        if current_distance > current_distance:
            continue

        for neighbor, weight in graph[current_node]:
            distance_through_current = current_distance + weight

            if distance_through_current < distance_dict[neighbor]:
                distance_dict[neighbor] = distance_through_current
                previous[neighbor] = current_node
                heapq.heappush(priority_queue, (distance_through_current, neighbor))

        if previous[target] is not None:
            final_node = target
            path = []
            while final_node:
                path.append(final_node)
                final_node = previous[final_node]
            return (distance_dict[target], path[::-1])

