def shortest_path(graph, source, target):
    # Initialize distances to unknown
    distances = {node: float('inf') for node in graph}

    from heapq import heappop, heappush
    # Priority queue with a tuple of (cost, visited_nodes, node, path)
    queue = [(0, "", node, [node]) for node in graph]
    visited = defaultdict(int)

    # Process nodes
    while queue:
        dist, prev, current, path = heappop(queue)

        # Shortest known path to this node, no need to continue searching
        if dist > distances[current]:
            continue

        # Mark current as visited
        visited[current] = prev

        # Stop when we reach the target
        if current == target:
            break

        # Explore neighbors
        for neighbor, weight in graph.get(current, []):
            alt = dist + weight
            path = path[:]  # Create another copy for heapq
            path.append(neighbor)

            if alt < distances[neighbor] and current not in path:
                distances[neighbor] = alt
                priority = alt + (neighbor not in visited.keys())
                heappush(queue, (priority, ','.join(path[:-2]), neighbor, path[:]))

    if distances[target] != float('inf'):
        return (distances[target], path)
    return (float('inf'), None)
