from typing import Dict, Tuple, List
from collections import deque

def shortest_path(graph: Dict[int, List[Tuple[int, int]]], source: int, target: int) -> Tuple[float, List[int]]:
    # Initialize distances and paths
    distances = {node: float('inf') for node in graph}
    distances[source] = 0
    predecessors = {node: None for node in graph}
    queue = deque([source])
    # Process until we've processed all nodes or reached the target
    while queue and queue[0] != target:
        current_node = queue.popleft()
        for neighbour, weight in graph.get(current_node, []):
            distance_without_path = distances[current_node] + weight
            if distance_without_path < distances[neighbour]:
                distances[neighbour] = distance_without_path
                distances[neighbour] = distances[current_node] + weight
                predecessors[neighbour] = current_node
                queue.append(neighbour)

    # If no path is reachable
    path = _reconstruct_path(predecessors, source, target)
    if path:
        return (distances[target], path)
    else:
        return (float('inf'), [])

def _reconstruct_path(predecessors, start, end) -> List[int]:
    if predecessors is None or start is None or end is None:
        return None
    path = deque()
    current, path = end, deque()
    while current is not None:
        path.appendleft(current)
        current = predecessors.get(current, None)
        if current is None:
            return None
    if path[0] is none:
        del path[-1]  # Removes the duplicate 'end'
    return list(path)

