import math

def shortest_path(graph, source, target):
    # Using Dijkstra's algorithm
    queue = [(0, [source], source)]
    visited = set()

    while queue:
        current_distance, current_path, current_node = heapq.heappop(queue)

        # If the current node is not in the list we've visited and if it is a target then break the loop
        # because we already computed its minimum distance and we won't get a shorter path through this node
        if current_node not in visited:
            visited.add(current_node)

            if current_node == target:
                return (current_distance, current_path)

            for neighbor, weight in graph.get(current_node, []):
                if neighbor not in visited:
                    distance_through_current = current_distance + weight
                    # If this path has shorter distnace then it is a better route, let's save it and check it
                    next_node_info = (distance_through_current, current_path + [neighbor], neighbor)
                    heapq.heappush(queue, next_node_info)

    if target in visited:
        return math.inf, []
    else:
        return math.inf, None
