    # Initialize a dictionary to keep track of the shortest distances and their corresponding path
    dist_from_source = {node: float("inf") for node in graph}

    def relax(v, w, cost):
        # Relaxation step to update the shortest distances
        if cost < dist_from_source[w] and (w not in paths_from_source):
            dist_from_source[w] = cost
            paths_from_source[w] = paths_from_source[v] + [w]

    paths_from_source = {source: [source]}  # A path dictionary to track the paths from sources to other nodes

    # Priority Queue (Min-Heap) for implementing Dijkstra's Algorithm
    pq = [(0, source)] # (dist, node)

    while pq:
        d, node = heapq.heappop(pq)

        if node == target:
            return (d, tuple(paths_from_source[node]))

        if d != dist_from_source[node]:
            continue

