import collections

def bellman_ford(graph, source):
    distances = {vertex: float('inf') for vertex in graph}
    distances[source] = 0
    predecessors = {vertex: None for vertex in graph}

    for _ in range(len(graph)):
        updated = False
        for vertex in graph:
            for neighbor, weight in graph[vertex]:
                if distances[vertex] + weight < distances[neighbor]:
                    distances[neighbor] = distances[vertex] + weight
                    predecessors[neighbor] = vertex
                    updated = True
        if not updated and _ > 0:
            return None, None
    return distances, predecessors

def find_shortest_path(graph, source, target):
    distances, predecessors = bellman_ford(graph, source)
    if target not in predecessors or distances[target] == float('inf'):
        return None, None  # Unreachable path or infinite distance
    path = []
    current_v = target
    if predecessors.get(current_v) == source:
        path.append(target)
        while current_v:
           path.insert(0, current_v)
           current_v = predecessors[current_v]
    else:  # There must be a way back to the original node to complete the path.
        return None, None 
    distance = distances[target]
    final_path = (''.join(str(vertex) for vertex in path), distance) if path else (False,)
    return final_path if final_path[0] else ('inf', None)

